// Tombstone for the retired coi-serviceworker (replaced by stelekit-service-worker.js in v0.70.0).
// Browsers that registered the old worker re-fetch this exact URL on their update check; a 404 leaves
// the stale worker in place, and it keeps the page cross-origin isolated so index.html never registers
// the new worker. Serving this instead lets the old registration upgrade to it, remove itself, and
// reload its clients so index.html can register stelekit-service-worker.js. Do not delete.
self.addEventListener("install", () => self.skipWaiting());
self.addEventListener("activate", (event) =>
    event.waitUntil(
        self.registration
            .unregister()
            .then(() => self.clients.matchAll({ type: "window" }))
            .then((clients) => clients.forEach((client) => client.navigate(client.url)))
    )
);
